// System Design — high-level design (HLD), low-level design (LLD) and AI/ML system design,
// from the basics to interview-ready.
//
// Ten phases. Every topic has:
//   - a one-line definition, and the interview notes: key points (concepts) or the full
//     design walk-through (design questions), a spoken interview answer, and follow-up
//     questions WITH answers, for quick revision before an interview,
//   - a plain-English explanation with an analogy and where it breaks (concepts),
//   - the problem it solves, how it works step by step, and common mistakes,
//   - free resources only, as optional extras (papers marked optional),
//   - one practice exercise for each of the four checks. No answers, on purpose.
//
// Fixed content only. Ticked checks live in Firestore under study_progress/system_design.

export type SDCheckKey = 'explain' | 'draw' | 'apply' | 'tradeoffs';

/** The order the checks are shown, practised and ticked in. */
export const SD_CHECK_KEYS: SDCheckKey[] = ['explain', 'draw', 'apply', 'tradeoffs'];

export const SD_CHECK_LABELS: Record<SDCheckKey, string> = {
    explain: 'Explain',
    draw: 'Draw',
    apply: 'Apply',
    tradeoffs: 'Trade-offs',
};

export const SD_CHECK_MEANINGS: Record<SDCheckKey, string> = {
    explain: 'Say it in plain words in under a minute, with no notes.',
    draw: 'Sketch the diagram (or class diagram) from memory.',
    apply: 'Use it in a real design question and say exactly where it fits.',
    tradeoffs: 'Say what it costs, when not to use it, and the alternative.',
};

export const SD_CONFIDENT_RULE =
    'A topic is finished when you pass all four checks, not when you finish a video. ' +
    'Be strict: if you needed your notes, it is not ticked yet.';

export type SDPriority = 'must' | 'should' | 'bonus';

export const SD_PRIORITY_LABELS: Record<SDPriority, string> = {
    must: 'Must know',
    should: 'Should know',
    bonus: 'Bonus',
};

/** Suggested order through the phases. */
export const sdHowToStudy: string[] = [
    'The notes on every topic are written to be enough on their own. The free resources are optional: a second explanation and extra practice.',
    'Start with Phase 0: the step-by-step answer frameworks for high-level and low-level design.',
    'HLD track: Phases 1 → 2 → 3 → 4, then practise with Phase 8.',
    'LLD track: Phases 5 → 6, then practise with Phase 7. You can run it alongside the HLD track.',
    'AI/ML track: Phase 9, once the core concepts and the ML Foundations AI-engineering topics feel solid.',
    'Graduate and junior interviews focus on the "Must know" topics. Learn those first; come back for the rest.',
    'Interview tomorrow? Use Revise mode with "Must know only".',
];

export type SDResourceKind = 'watch' | 'read' | 'code' | 'paper';

export const SD_RESOURCE_KIND_ORDER: SDResourceKind[] = ['watch', 'read', 'code', 'paper'];

export interface SDResource {
    kind: SDResourceKind;
    /** The exact title, so it stays findable even if a link moves. */
    title: string;
    source: string;
    /** A direct link, or a search link where the exact page is likely to move. Every resource is free. */
    url?: string;
}

export interface SDFollowUp {
    q: string;
    a: string;
}

interface SDTopicBase {
    /** Stable id, used as the Firestore key. Never renumber: ids need not match display order. */
    id: string;
    name: string;
    priority: SDPriority;
    /** One sentence. Say this first in an interview. */
    definition: string;
    /** Why this exists: the problem it solves (concepts), or why interviewers ask it (designs). */
    problem: string;
    /** Common mistakes and misunderstandings to avoid. */
    mistakes: string[];
    /** A 20–40 second spoken answer for the interview. */
    interviewAnswer: string;
    /** Likely follow-up questions, with short answers for revision. */
    followUps: SDFollowUp[];
    practice: Record<SDCheckKey, string>;
    resources: SDResource[];
    code?: string;
    codeLanguage?: 'python' | 'sql' | 'text';
}

/** A building block: a concept, principle or pattern. */
export interface SDConcept extends SDTopicBase {
    kind: 'concept';
    idea: string;
    /** How it works, step by step, with a running example. */
    howItWorks: string[];
    analogy: string;
    /** Where the analogy stops being true — the part that stops you learning it wrong. */
    breaks: string;
    example: string;
    /** The must-know facts. Don't skip these. */
    keyPoints: string[];
    tradeOffs?: string[];
}

/** A full design question, walked through with the interview framework. */
export interface SDDesign extends SDTopicBase {
    kind: 'design';
    designType: 'hld' | 'lld' | 'ml';
    functional: string[];
    nonFunctional: string[];
    estimates?: string[];
    api?: string[];
    dataModel?: string[];
    /** LLD: the main classes and what each one does. */
    classes?: string[];
    patterns?: string[];
    /** Start simple, then scale: how the design grows from version 1 to the final version. */
    evolution: string[];
    /** The design, step by step. */
    design: string[];
    deepDives: string[];
}

export type SDTopic = SDConcept | SDDesign;

export interface SDPhase {
    id: string;
    number: number;
    short: string;
    title: string;
    accent: string;
    goal: string;
    bigPicture: string;
    topics: SDTopic[];
}

